package org.sleepwell.app;

import android.app.*;
import android.content.DialogInterface;
import android.os.Bundle;
import android.graphics.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;

/** Board 08 history and calendar-based trends, backed by saved effective records. */
public final class HistoryActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private List<RecordEntry> records=List.of();private boolean loaded,trends,searching;private String query="",filter="All",failure="";private LocalDate day,anchor=LocalDate.now();private int period,generation;private long selected;
    private LinearLayout list;private TextView helper;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);if(state!=null){trends=state.getBoolean("trends");searching=state.getBoolean("searching");query=state.getString("query","");filter=state.getString("filter","All");period=state.getInt("period");selected=state.getLong("selected");anchor=LocalDate.parse(state.getString("anchor",LocalDate.now().toString()));String date=state.getString("day");if(date!=null)day=LocalDate.parse(date);}render();}
    @Override protected void onResume(){super.onResume();load();}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("trends",trends);state.putBoolean("searching",searching);state.putString("query",query);state.putString("filter",filter);state.putInt("period",period);state.putLong("selected",selected);state.putString("anchor",anchor.toString());if(day!=null)state.putString("day",day.toString());}
    private int cutoff(){return Math.max(0,Math.min(1439,Prefs.number(this,"statsCutoff",0)));}
    private long goal(){return Math.max(1,Prefs.number(this,"goal",480))*60000L;}
    private void load(){int request=++generation;worker.execute(()->{try(Store store=Records.open(this)){List<RecordEntry> entries=Records.all(store);runOnUiThread(()->{if(isDestroyed()||request!=generation)return;records=entries;loaded=true;failure="";render();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;failure="Records could not be read. "+e.getMessage();render();});}});}
    private void render(){LinearLayout body=Design.page(this,false,1,destination->RecordUi.main(this,destination));RecordUi.label(this,body);
        if(!failure.isEmpty()){RecordUi.header(body,"Sleep history",null);Design.space(body,24);Design.text(body,failure,15,400,Design.MUTED);Design.button(body,"Try again",true,this::load);return;}
        if(!loaded){RecordUi.header(body,"Sleep history",null);Design.space(body,24);Design.text(body,"Loading records…",15,400,Design.MUTED);return;}
        if(trends){trends(body);return;}
        LinearLayout header=RecordUi.header(body,"Sleep history",null);RecordUi.headerAction(header,"report","Trends",()->{trends=true;render();});RecordUi.headerAction(header,searching?"close":"search","Search records",()->{searching=!searching;if(!searching)query="";render();});
        if(searching){EditText search=new EditText(this);search.setSingleLine();search.setTextSize(14*Appearance.scale(this));search.setTypeface(Design.font(this,400));search.setTextColor(Design.INK);search.setHintTextColor(Design.MUTED);search.setHint("Notes, tags or date");search.setContentDescription("Search notes and tags");search.setText(query);search.setBackground(Design.shape(this,Design.SOFT,12));Design.pad(search,12,8);body.addView(search,new LinearLayout.LayoutParams(-1,Design.dp(this,48)));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){query=s.toString();populate();}public void afterTextChanged(Editable e){}});}
        LinearLayout filters=Design.row(this);HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout choices=Design.row(this);scroll.addView(choices);filters.addView(scroll,new LinearLayout.LayoutParams(0,Design.dp(this,48),1));for(String name:new String[]{"All","Good sleep","Late night","Short"}){View chip=RecordUi.chip(this,name,filter.equals(name),()->{filter=name;render();});choices.addView(chip,new LinearLayout.LayoutParams(-2,Design.dp(this,48)));}filters.addView(Design.iconButton(this,"calendar","Filter by date",this::chooseDay),new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(filters);
        helper=Design.text(body,"",11,400,Design.MUTED);list=Design.col(this);body.addView(list);populate();
    }
    private boolean matches(RecordEntry r){if(day!=null&&!r.day(cutoff()).equals(day))return false;if(filter.equals("Good sleep")&&(!r.edit.rated||r.edit.rating<4))return false;if(filter.equals("Late night")&&!RecordTrends.late(r,Prefs.number(this,"bedtime",1350)))return false;if(filter.equals("Short")&&r.duration()>=goal())return false;String hay=r.edit.note+" "+String.join(" ",r.edit.tags)+" "+RecordUi.date(r.edit.end,r.zone())+" "+r.provenance();return hay.toLowerCase(Locale.ROOT).contains(query.trim().toLowerCase(Locale.ROOT));}
    private void populate(){if(list==null)return;list.removeAllViews();String definition=filter.equals("Good sleep")?"Your rested rating: 4–5.":filter.equals("Late night")?"Starts over 30 min after your bedtime goal.":filter.equals("Short")?"Duration below your saved goal.":"Recorded and user-reported periods.";helper.setVisibility(day==null&&filter.equals("All")?View.GONE:View.VISIBLE);helper.setText(day==null?definition:day.format(DateTimeFormatter.ofPattern("EEE d MMM",Locale.getDefault()))+" · "+definition);
        List<RecordEntry> shown=new ArrayList<>();for(RecordEntry record:records)if(matches(record))shown.add(record);shown.sort(Comparator.comparing((RecordEntry r)->r.day(cutoff())).reversed().thenComparing(Comparator.comparingLong((RecordEntry r)->r.edit.start).reversed()));
        if(shown.isEmpty()){monthHeader(list,day==null?"Your records":day.format(DateTimeFormatter.ofPattern("MMMM uuuu",Locale.getDefault())));Design.space(list,36);Design.text(list,records.isEmpty()?"No records yet":"No matching records",22,600,Design.INK);Design.space(list,10);Design.text(list,records.isEmpty()?"Track a night or add a sleep period you remember.":"Try another date, search or filter.",14,400,Design.MUTED);return;}
        String month="";for(RecordEntry r:shown){String next=r.day(cutoff()).format(DateTimeFormatter.ofPattern("MMMM uuuu",Locale.getDefault()));if(!next.equals(month)){month=next;monthHeader(list,month);}recordRow(list,r);}
    }
    private void monthHeader(LinearLayout body,String month){LinearLayout row=Design.row(this);row.addView(Design.text(this,month,15,600,Design.INK),new LinearLayout.LayoutParams(0,-2,1));TextView add=Design.text(this,"Add sleep  +",14,600,Design.INK);add.setGravity(Gravity.CENTER);add.setMinimumHeight(Design.dp(this,48));add.setContentDescription("Add sleep");add.setOnClickListener(v->open(0));row.addView(add);body.addView(row);}
    private void recordRow(LinearLayout body,RecordEntry r){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,76));Design.pad(row,4,8);if(selected==r.id||selected==0&&records.indexOf(r)==0)row.setBackground(Design.touch(this,Design.SOFT,14));else row.setBackground(Design.touch(this,Color.TRANSPARENT,14));
        LinearLayout date=Design.col(this);Design.text(date,r.day(cutoff()).format(DateTimeFormatter.ofPattern("EEE",Locale.getDefault())),13,600,Design.INK);Design.space(date,4);Design.text(date,r.day(cutoff()).format(DateTimeFormatter.ofPattern("d MMM",Locale.getDefault())),11,400,Design.MUTED);row.addView(date,new LinearLayout.LayoutParams(Design.dp(this,56),-2));
        LinearLayout middle=Design.col(this);middle.addView(new CoverageStrip(r),new LinearLayout.LayoutParams(-1,Design.dp(this,18)));Design.space(middle,5);LinearLayout times=Design.row(this);TextView start=Design.text(this,RecordUi.clock(this,r.edit.start,r.zone()),11,400,Design.MUTED),end=Design.text(this,RecordUi.clock(this,r.edit.end,r.zone()),11,400,Design.MUTED);start.setCompoundDrawables(RecordUi.glyph(this,"moon",Design.VIOLET,10),null,null,null);start.setCompoundDrawablePadding(Design.dp(this,2));end.setCompoundDrawables(RecordUi.glyph(this,"sun",Design.BROWN,10),null,null,null);end.setCompoundDrawablePadding(Design.dp(this,2));times.addView(start,new LinearLayout.LayoutParams(0,-2,1));end.setGravity(Gravity.START);times.addView(end,new LinearLayout.LayoutParams(0,-2,1));middle.addView(times);row.addView(middle,new LinearLayout.LayoutParams(0,-2,1));
        LinearLayout result=Design.col(this);result.setGravity(Gravity.END);TextView duration=Design.text(this,"",19,600,Design.INK);duration.setText(RecordUi.units(RecordUi.duration(r.duration())));result.addView(duration);Design.space(result,4);Design.text(result,r.manual()?"Manual":r.edited?"Edited":r.interrupted==1?"Interrupted":"Recorded",9,400,Design.MUTED).setGravity(Gravity.END);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(Design.dp(this,94),-2);rp.leftMargin=Design.dp(this,10);row.addView(result,rp);Design.Icon arrow=new Design.Icon(this,"chevron",Design.INK);row.addView(arrow,new LinearLayout.LayoutParams(Design.dp(this,18),Design.dp(this,18)));row.setContentDescription("Open record "+r.id+", "+r.day(cutoff())+", "+RecordUi.duration(r.duration())+", "+r.provenance());row.setOnClickListener(v->{selected=r.id;open(r.id);});body.addView(row);Design.line(body);
    }
    private void open(long id){startActivity(RecordUi.intent(this,RecordEditorActivity.class).putExtra("record",id));}
    private void chooseDay(){LocalDate selected=day==null?LocalDate.now():day;DatePickerDialog picker=new DatePickerDialog(this,(v,y,m,d)->{day=LocalDate.of(y,m+1,d);populate();},selected.getYear(),selected.getMonthValue()-1,selected.getDayOfMonth());picker.setTitle("Records ending on");picker.setButton(DialogInterface.BUTTON_NEUTRAL,"All dates",(d,w)->{day=null;populate();});picker.show();}
    private void trends(LinearLayout body){LinearLayout header=RecordUi.header(body,"Trends",null);RecordUi.headerAction(header,"calendar","Sleep history",()->{trends=false;render();});Design.space(body,10);RecordUi.segments(body,new String[]{"Week","Month","Year"},period,index->{period=index;render();});Design.space(body,12);
        TextView rangeButton=Design.text(this,period==0?"Week ending "+anchor.format(DateTimeFormatter.ofPattern("d MMM uuuu",Locale.getDefault())):anchor.format(DateTimeFormatter.ofPattern(period==1?"MMMM uuuu":"uuuu",Locale.getDefault())),12,400,Design.MUTED);rangeButton.setMinHeight(Design.dp(this,40));rangeButton.setGravity(Gravity.CENTER_VERTICAL);rangeButton.setContentDescription("Choose trend date");rangeButton.setOnClickListener(v->chooseAnchor());
        RecordTrends.Range range=RecordTrends.range(anchor,period);SortedMap<LocalDate,RecordTrends.Day> days=RecordTrends.days(records,range,cutoff());LinearLayout totals=Design.row(this),average=Design.col(this),gap=Design.col(this);Design.text(average,"Average duration",14,600,Design.INK);Design.space(average,6);TextView avg=Design.text(average,days.isEmpty()?"—":RecordUi.duration(RecordTrends.average(days.values())),42,700,Design.INK);avg.setText(RecordUi.units(avg.getText().toString()));totals.addView(average,new LinearLayout.LayoutParams(0,-2,1));View divider=new View(this);divider.setBackgroundColor(Design.LINE);LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(Design.dp(this,1),Design.dp(this,76));dp.setMargins(Design.dp(this,8),0,Design.dp(this,16),0);totals.addView(divider,dp);Design.text(gap,"Goal gap",12,400,Design.MUTED);Design.space(gap,8);long deficit=RecordTrends.goalGap(days.values(),goal());TextView missing=Design.text(gap,days.isEmpty()?"—":RecordUi.duration(Math.max(0,deficit)),19,600,Design.INK);missing.setText(RecordUi.units(missing.getText().toString()));Design.space(gap,4);Design.text(gap,"recorded days",10,400,Design.MUTED);totals.addView(gap,new LinearLayout.LayoutParams(Design.dp(this,88),-2));body.addView(totals);Design.space(body,8);Design.text(body,days.size()+" recorded days · missing dates excluded",11,400,Design.MUTED);
        if(period==2){Design.space(body,4);Design.text(body,"Monthly averages of recorded days",11,400,Design.MUTED);}RecordUi.heading(body,"Recorded duration");body.addView(new TrendsChart(this,days,range,period,false,goal()),new LinearLayout.LayoutParams(-1,Design.dp(this,174)));RecordUi.heading(body,"Bedtime consistency");body.addView(new TrendsChart(this,days,range,period,true,goal()),new LinearLayout.LayoutParams(-1,Design.dp(this,128)));Design.space(body,6);Design.text(body,"Main periods of 3 h or longer; tagged naps excluded.",10,400,Design.MUTED);Design.space(body,8);body.addView(rangeButton);Design.item(body,"calendar","Day boundary",String.format(Locale.getDefault(),"%02d:%02d",cutoff()/60,cutoff()%60),this::chooseCutoff);Design.text(body,"Totals merge overlaps. Duration includes tracked time awake unless you mark it. Manual periods are user-reported.",11,400,Design.MUTED);
    }
    private void chooseAnchor(){new DatePickerDialog(this,(v,y,m,d)->{anchor=LocalDate.of(y,m+1,d);render();},anchor.getYear(),anchor.getMonthValue()-1,anchor.getDayOfMonth()).show();}
    private void chooseCutoff(){int minutes=cutoff();new TimePickerDialog(this,(v,h,m)->{Prefs.put(this,"statsCutoff",h*60+m);render();},minutes/60,minutes%60,android.text.format.DateFormat.is24HourFormat(this)).show();}
    private final class CoverageStrip extends View {private final RecordEntry record;private final Paint p=new Paint(3);CoverageStrip(RecordEntry record){super(HistoryActivity.this);this.record=record;setContentDescription(record.manual()?"User-reported interval; no sensor measurements":"Recorded intervals; blank spaces are pauses or awake edits");}
        @Override protected void onDraw(Canvas c){super.onDraw(c);long span=Math.max(1,record.edit.end-record.edit.start);float top=getHeight()*.25f,bottom=getHeight()*.8f;p.setColor(0xffeee5f5);c.drawRoundRect(0,top,getWidth(),bottom,4,4,p);p.setColor(record.manual()?0xffc5a7ee:Design.VIOLET);for(RecordIntervals.Span s:record.coverage()){float a=getWidth()*(s.start-record.edit.start)/(float)span,b=getWidth()*(s.end-record.edit.start)/(float)span;c.drawRoundRect(a,top,b,bottom,4,4,p);}}
    }
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
}
